const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry around Peoria, Illinois
  const peoria = ee.Geometry.Point([-89.59, 40.69]);
  const aoi = peoria.buffer(15000); // 15km radius for agricultural areas

  // 2. Define date ranges
  const sept2022 = ee.DateRange('2022-09-01', '2022-09-30');
  const oct2022 = ee.DateRange('2022-10-01', '2022-10-31');

  // 3. Load Sentinel-2 collection with cloud masking
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  }

  // 4. Get September data
  let septCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(sept2022.start(), sept2022.end())
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  let septSize = septCol.size().getInfo();
  console.log('September 2022 Images:', septSize);

  // Fallback to Landsat 8 if Sentinel-2 unavailable
  if (septSize === 0) {
    console.log('Trying Landsat 8 for September...');
    septCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(sept2022.start(), sept2022.end())
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    septSize = septCol.size().getInfo();
    console.log('Landsat September Images:', septSize);
  }

  if (septSize === 0) {
    console.log('No data for September 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get October data
  let octCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(oct2022.start(), oct2022.end())
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(maskS2clouds);

  let octSize = octCol.size().getInfo();
  console.log('October 2022 Images:', octSize);

  // Fallback to Landsat 8 if Sentinel-2 unavailable
  if (octSize === 0) {
    console.log('Trying Landsat 8 for October...');
    octCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(oct2022.start(), oct2022.end())
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    octSize = octCol.size().getInfo();
    console.log('Landsat October Images:', octSize);
  }

  if (octSize === 0) {
    console.log('No data for October 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate NDVI for both periods
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const septImage = septCol.map(addNDVI).median();
  const octImage = octCol.map(addNDVI).median();

  // 7. Get statistics
  const septStats = septImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  const octStats = octImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  const septNDVI = septStats.get('NDVI_mean').getInfo();
  const septCount = septStats.get('NDVI_count').getInfo();
  const octNDVI = octStats.get('NDVI_mean').getInfo();
  const octCount = octStats.get('NDVI_count').getInfo();

  console.log('September NDVI:', septNDVI, 'Pixels:', septCount);
  console.log('October NDVI:', octNDVI, 'Pixels:', octCount);

  // 8. Validation and answer
  if (septCount === 0 || octCount === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (septNDVI === null || octNDVI === null || isNaN(septNDVI) || isNaN(octNDVI)) {
    console.log('Calculation failed - invalid NDVI values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (septNDVI > 1 || octNDVI > 1 || septNDVI < -1 || octNDVI < -1) {
    console.log('Invalid NDVI range detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Lower NDVI in October means more brown/senescent vegetation
  const ndviDecrease = septNDVI - octNDVI;
  console.log('NDVI Decrease (Sept to Oct):', ndviDecrease.toFixed(4));

  if (ndviDecrease > 0.05) {
    console.log('Significant decrease in NDVI - more brown fields in October.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant increase in brown fields.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
